const test=require('node:test'),assert=require('node:assert/strict');
test('non-rendered board hit surfaces still support tile selection',async()=>{const T=await import('../vendor/three.module.js');const material=new T.MeshBasicMaterial({visible:false,side:T.DoubleSide});const mesh=new T.Mesh(new T.PlaneGeometry(10,10),material);mesh.rotation.x=-Math.PI/2;mesh.userData.cell={q:0,r:0};mesh.updateMatrixWorld(true);const ray=new T.Raycaster(new T.Vector3(0,5,0),new T.Vector3(0,-1,0));assert.equal(ray.intersectObject(mesh)[0].object.userData.cell.q,0);assert.equal(material.visible,false);});
